import sys
sys.path.insert(0, "/tmp/<path>")
from duration import parse_duration as p

ok = {
    "1h30m": 5400, " 2d 4h ": 187200, "1.5h": 5400, "1w2d3h4m5s": 788645,
    "1:02:03": 3723, "-45s": -45, "0": 0, "1:30": 90, "1:00:00": 3600,
    "90:00": 5400, "-1h": -3600, "-1:30": -90, "-0s": 0, "05m": 300,
    "1.5m": 90, "0.1h": 360, "0.25h": 900, "1h 30m": 5400, "0s": 0,
    "-0": 0, "1w": 604800, "10s": 10, "1.5w": 907200,
}
bad = [
    "", "   ", ".5h", "5.h", "1 h", "30m1h", "1h1h", "0.3s", "1:60", "1:5",
    "5", "1.5", "+1h", "1h  30m", "1H", "1x", "1:2:3", "1:600", "00", "1.2.3h",
    "- 1h", "--1h", "1:30:", ":30", "1h\t30m", "1m30", "1:-30", "1.:30", "-",
    "1d1w", "1h-30m", "1:30.5", "١h",
]
fails = 0
for s, want in ok.items():
    try:
        got = p(s)
        if got != want or type(got) is not int:
            print("WRONG", repr(s), got, want); fails += 1
    except Exception as e:
        print("RAISED", repr(s), e); fails += 1
for s in bad:
    try:
        print("ACCEPTED", repr(s), p(s)); fails += 1
    except ValueError:
        pass
    except Exception as e:
        print("WRONG EXC", repr(s), type(e).__name__); fails += 1
for x in (None, 5, 1.5, b"1h"):
    try:
        p(x); print("NO TypeError", x); fails += 1
    except TypeError:
        pass
print("failures:", fails)
EOF
cd /tmp/skv-duration-tests && python3 -I check.py
